function tokensOf(map) {
  var out = [];
  (map && map.Elements || []).forEach(function (e) {
    var o;
    try { o = JSON.parse(e.Object || "{}"); } catch (x) { return; }
    if (!o.isToken) return;
    var w = (o.width || 0) * (o.scaleX || 1), h = (o.height || 0) * (o.scaleY || 1);
    var x = o.originX === "center" ? o.left : (o.left || 0) + w / 2;
    var y = o.originY === "center" ? o.top : (o.top || 0) + h / 2;
    out.push({ id: String(e.Id), name: o.name || "token", x: x, y: y, r: Math.min(w, h) / 2 });
  });
  return out;
}var grid = (vars.fb_map && vars.fb_map.GridSize) || 50;
var radius = parseFloat(vars.radiusSquares || "4") * grid;
var p = vars.position || { x: 0, y: 0 };
var hits = tokensOf(vars.fb_map).filter(function (t) {
  return Math.sqrt(Math.pow(t.x - p.x, 2) + Math.pow(t.y - p.y, 2)) <= radius + t.r;
}).map(function (t) { return { id: t.id, name: t.name }; });
return {
  fb_targets: hits,
  fb_count: hits.length,
  fb_names: hits.length ? hits.map(function (t) { return t.name; }).join(", ") : "nobody"
};

var a = String(vars.fb_answer == null ? "" : vars.fb_answer).trim().toLowerCase();
var dmg = Number(vars.fb_damage) || 0;
var final = 0, text;
if (vars.fb_count === 0) text = "The Fireball hit nobody.";
else if (["yes", "y", "tak", "t", "full"].indexOf(a) >= 0) { final = dmg; text = "The GM applied " + dmg + " fire damage to " + vars.fb_count + " creature(s)."; }
else if (["half", "h", "pol", "pół", "polowa", "połowa"].indexOf(a) >= 0) { final = Math.floor(dmg / 2); text = "The GM applied half (" + final + ") to " + vars.fb_count + " creature(s)."; }
else if (a) text = "The GM didn't apply the damage.";
else text = "The GM didn't answer: no damage applied.";
return { damage: final, fb_apply: final > 0 && vars.fb_count > 0 ? 1 : 0, fb_text: text };
